def _decode(s):
    return _gz.decompress(_b64.b64decode(s))

_TEMPLATE_NAME = "takeda_template_fruzaqla.pptx"
_BANNER_NAME = "takeda_fruq_banner.png"
_SEARCH_DIRS = ["/mnt/project", "/home/claude", "/mnt/user-data/uploads", _os.getcwd()]

def _find_on_disk(name):
    for d in _SEARCH_DIRS:
        p = _os.path.join(d, name)
        if _os.path.exists(p):
            return p
    try:
        import takeda_remote as _remote
        return _remote.get(name)   # download from GitHub
    except Exception:
        return None

def _seed_template_from_disk():
    src = _find_on_disk(_TEMPLATE_NAME)
    dst = _os.path.join(_CACHE_DIR, "takeda_fruzaqla.pptx")
    if src and not _os.path.exists(dst):
        import shutil as _sh; _sh.copyfile(src, dst)

def _seed_banner_from_disk():
    src = _find_on_disk(_BANNER_NAME)
    dst = _os.path.join(_CACHE_DIR, "chrome_fruq_banner.png")
    if src and not _os.path.exists(dst):
        import shutil as _sh; _sh.copyfile(src, dst)

def template_path(brand="FRUZAQLA"):
    """Path to the FRUZAQLA template .pptx (disk attachment)."""
    p = _find_on_disk(_TEMPLATE_NAME)
    if not p:
        raise FileNotFoundError("FRUZAQLA template not found. Attach '" + _TEMPLATE_NAME +
                                "' to the project or place it in: " + repr(_SEARCH_DIRS))
    return p

# Register into the shared registry that takeda.py reads. A global dict on builtins
# lets multiple brand modules coexist; importing several makes several available.
import builtins as _bi
if not hasattr(_bi, "_TAKEDA_TEMPLATE_REGISTRY"):
    _bi._TAKEDA_TEMPLATE_REGISTRY = {}
if not hasattr(_bi, "_TAKEDA_CHROME_REGISTRY"):
    _bi._TAKEDA_CHROME_REGISTRY = {}
if not hasattr(_bi, "_TAKEDA_CHROME_GEOMETRY"):
    _bi._TAKEDA_CHROME_GEOMETRY = {}

_bi._TAKEDA_TEMPLATE_REGISTRY["FRUZAQLA"] = "__DISK__"
try:
    _seed_template_from_disk()
except Exception:
    pass
_bi._TAKEDA_CHROME_REGISTRY["FRUQ_BANNER"] = CHROME_FRUQ_BANNER_B64GZ
_bi._TAKEDA_CHROME_REGISTRY["FRUQ_LOGO"] = CHROME_FRUQ_LOGO_B64GZ
# Merge geometry without clobbering other brands' entries already present.
for _k, _v in CHROME_GEOMETRY.items():
    _bi._TAKEDA_CHROME_GEOMETRY.setdefault(_k, _v)
# These are FRUZAQLA-owned; override any stale geometry from earlier module versions.
_bi._TAKEDA_CHROME_GEOMETRY["FRUQ_BANNER"] = CHROME_GEOMETRY["FRUQ_BANNER"]
_bi._TAKEDA_CHROME_GEOMETRY["FRUQ_LOGO"] = CHROME_GEOMETRY["FRUQ_LOGO"]

_EXT = {}  # all FRUZAQLA chrome is PNG


def chrome_path(name):
    """Path to a decoded chrome image (gunzipped to /tmp on first call)."""
    reg = _bi._TAKEDA_CHROME_REGISTRY
    if name not in reg:
        raise KeyError(f"Chrome {name!r} not loaded. Import the owning brand module. "
                       f"Loaded: {sorted(reg)}")
    ext = _EXT.get(name, "png")
    path = _os.path.join(_CACHE_DIR, f"chrome_{name.lower()}.{ext}")
    if not _os.path.exists(path):
        with open(path, "wb") as f:
            f.write(_decode(reg[name]))
    return path
